using UnityEngine;
using UnityEngine.UI;
public static class VoyageSoundControls {
 public static void Add(VoyageUI ui,Transform parent,float y){Make(ui,parent,"Ana ses","Master",y,.85f);Make(ui,parent,"Müzik","Music",y-140,.7f);}
 static void Make(VoyageUI ui,Transform parent,string title,string key,float y,float initial){ui.Label(title,parent,new Vector2(-40,y),new Vector2(520,45),title,28);var value=ui.Label(title+" value",parent,new Vector2(270,y-55),new Vector2(100,55),"",26);var track=ui.Picture(title+" slider",parent,new Vector2(-30,y-55),new Vector2(450,66),"volume_track");var slider=track.gameObject.AddComponent<Slider>();var travel=ui.Rect("Slider travel",track.transform,Vector2.zero,Vector2.zero);travel.anchorMin=Vector2.zero;travel.anchorMax=Vector2.one;travel.offsetMin=new Vector2(49,23);travel.offsetMax=new Vector2(-49,-23);var fill=ui.Picture("Volume fill",travel,Vector2.zero,Vector2.zero,"slider_fill");fill.rectTransform.anchorMin=Vector2.zero;fill.rectTransform.anchorMax=Vector2.one;fill.rectTransform.offsetMin=fill.rectTransform.offsetMax=Vector2.zero;var handleTravel=ui.Rect("Knob travel",track.transform,Vector2.zero,Vector2.zero);handleTravel.anchorMin=Vector2.zero;handleTravel.anchorMax=Vector2.one;handleTravel.offsetMin=new Vector2(49,13);handleTravel.offsetMax=new Vector2(-49,-13);var knob=ui.Picture("Volume knob",handleTravel,Vector2.zero,new Vector2(42,0),"slider_knob");knob.preserveAspect=true;slider.fillRect=fill.rectTransform;slider.handleRect=knob.rectTransform;slider.targetGraphic=knob;slider.minValue=0;slider.maxValue=1;slider.value=PlayerPrefs.GetFloat("Sound."+key,initial);value.text=Mathf.RoundToInt(slider.value*100)+"%";slider.onValueChanged.AddListener(v=>{value.text=Mathf.RoundToInt(v*100)+"%";PlayerPrefs.SetFloat("Sound."+key,v);PlayerPrefs.Save();AudioListener.volume=PlayerPrefs.GetFloat("Sound.Master",.85f);});}
}
